    , indvdlinfo_colct_agre_at
    , markt_colct_agre_at
    , email_colct_agre_at
    , sms_colct_agre_at
    , sbscrb_dt
    , last_conect_dt
    , mber_sttus_code
    , sttus_change_dt
    , mber_sbscrb_ty_code
    , creat_mber_no
    , creat_dt
    , change_mber_no
    , change_dt
)
